"""Shot list -> shots/NN.json (Flow prompts). Dialogue is spoken in Uzbek so lip movement fits the dub.
python shots.py          # write all json files
"""
import json, os

HERE = os.path.dirname(os.path.abspath(__file__))
R = lambda n: f'refs/{n}.jpg'  # character / location reference images, relative to this folder
W, M, H, MO, S, PAW, ROOM = R('mrwhite'), R('mrswhite'), R('herbert'), R('morris'), R('stranger'), R('paw'), R('parlour')

STYLE = (" Cinematic period drama, England 1902, 35mm film look with natural grain, shallow depth of field, "
         "realistic physics and natural human motion, restrained realistic acting, consistent faces and costumes as in the reference images. "
         "No subtitles, no captions, no text, letters or watermark anywhere in the frame, no music.")
TALK = " Lip movement matches the spoken Uzbek words."
SILENT = " No one speaks."

# number, seconds, refs, prompt
SHOTS = [
 (1, '8s', [ROOM], "Exterior at night in a violent storm: a small lonely brick cottage stands beside a muddy country road, its single window glowing warm orange. Rain sweeps sideways in the wind, bare trees thrash, a wooden garden gate swings and bangs. Slow steady push-in toward the lit window. Sound: howling wind, heavy rain, distant thunder." + SILENT),
 (2, '10s', [W, H, ROOM], "Inside the warm parlour by the crackling fireplace, Mr White (the old balding man with spectacles and white sideburns) and his son Herbert (the young man in the flat cap) play chess at a small table. A gust rattles the window. Mr White looks up and says in Uzbek: \"Shamolning ovozini qara.\" Herbert grins, moves a chess piece and says in Uzbek: \"Eshityapman, ota. Shoh!\" Mr White frowns at the board. Slow gentle dolly around the table. Sound: fire crackling, wind outside." + TALK),
 (3, '6s', [W, M, ROOM], "In the parlour, a gate clangs outside and heavy footsteps approach. Mr White rises from his armchair, peering toward the dark hallway, and says in Uzbek: \"Ana, keldi.\" Mrs White (the grey-haired woman in the green dress and cream shawl) lowers her knitting. Static medium shot." + TALK),
 (4, '8s', [W, MO], "A narrow dim hallway. The front door opens onto the stormy night and Sergeant-Major Morris (the burly man with the grey walrus moustache and tweed coat) steps inside, shaking rain from his coat. Mr White shakes his hand warmly and says in Uzbek: \"Kiring, Morris, kiring!\" Wind and rain gust through the doorway." + TALK),
 (5, '10s', [W, MO, H], "By the fire, Morris sits in an armchair holding a glass of whisky, firelight on his ruddy face, while Mr White (balding, white sideburns, round spectacles, as in the reference) and Herbert listen eagerly. Morris says in a low voice in Uzbek: \"Hindistonda yigirma bir yil... Ibodatxonalar, darveshlar... Siz ishonmaydigan narsalar.\" Slow push-in on Morris." + TALK),
 (6, '10s', [H, MO, ROOM], "In the firelit parlour Herbert leans forward in his chair, eyes bright, and asks in Uzbek: \"Otamga maymun panjasi haqida nimadir aytayotgan edingiz-ku?\" Morris stiffens, his face hardening, and answers curtly in Uzbek: \"Hech narsa. Eshitishga arzimaydigan gap.\" Over-the-shoulder framing." + TALK),
 (7, '10s', [MO], "Close-up by the fire: Morris slowly draws from his coat pocket a small old monkey-paw talisman, a shrivelled dark brown charm tied with a faded red cord and holds it in his open palm in the firelight. He says gravely in Uzbek: \"Bir keksa darvesh unga sehr o'qigan. Uch kishining har biri uchtadan tilak tilashi mumkin.\" Slow push-in on the paw, then tilt up to his eyes." + TALK),
 (9, '10s', [MO, W], "In the parlour Morris suddenly tosses the monkey-paw talisman into the fireplace. Mr White quickly kneels and pulls it out of the edge of the flames with iron fire tongs. Morris says sharply in Uzbek: \"Yonib ketgani ma'qul!\" Mr White, holding the paw, answers in Uzbek: \"Kerak bo'lmasa, menga bering.\"" + TALK),
 (10, '8s', [MO], "In the dim hallway Morris buttons his heavy tweed coat at the open front door, turns back with a grave look and says quietly in Uzbek: \"Agar albatta tilasangiz... aqlliroq narsa tilang.\" Then he steps out into the pitch-black stormy night and is gone; it is night outside, dark and wet, rain blows in through the doorway." + TALK),
 (11, '8s', [H, M], "In the parlour Herbert holds the monkey-paw talisman up, laughing, and says playfully in Uzbek: \"Imperator bo'lishni tilang, ota!\" Mrs White smiles and lightly swats his arm." + TALK),
 (12, '10s', [W, H, ROOM], "A warm, quiet family moment by the fireplace. Mr White sits in his armchair looking thoughtfully at a small old good-luck charm resting in his palm, shrugs with a shy smile and says a short sentence to his son. His son Herbert, leaning on the mantelpiece, grins and answers him with a cheerful short sentence. Soft firelight, gentle mood. Natural conversation with visible lip movement." + STYLE),
 (13, '10s', [W, M], "In the parlour Mr White stands and raises the monkey-paw talisman in his right hand and says solemnly in Uzbek: \"Ikki yuz funt tilayman.\" Suddenly he flinches, cries out and drops it onto the rug, staring at his own hand, and shouts in Uzbek: \"Qimirladi! Qo'limda ilondek to'lg'andi!\" Mrs White jumps up from her chair in alarm." + TALK),
 (14, '8s', [H, W], "Mr White and Herbert stare down at the monkey-paw talisman lying motionless on the rug; firelight throws long trembling shadows. Herbert breaks the tension with a nervous laugh and says in Uzbek: \"Pul ko'rinmayapti-ku. Hech qachon ko'rinmaydi ham.\"" + TALK),
 (15, '8s', [H, ROOM], "Late at night Herbert sits alone before the dying embers of the parlour fireplace, the room dark. He stares into the glowing coals. For a brief moment the cracks and shadows of the embers seem to suggest a faint grotesque face, subtle and ambiguous, made only of glowing coal and shadow, no animal and no creature. He recoils, catches his breath, then shakes his head. Sound: low wind, ticking clock." + SILENT),
 (16, '10s', [H, M, W], "Bright winter morning, sunlight streams through the window onto a breakfast table. Herbert pulls on his flat cap, gives his mother a quick hug, turns to his father and says a short cheerful sentence with a wink. He walks out the door while his parents smile after him. Natural lip movement while he speaks." + STYLE),
 (17, '8s', [M, S], "Grey overcast afternoon. Mrs White stands at the parlour window looking out through lace curtains: at the garden gate a well-dressed man in black with a top hat (the man from the reference image) hesitates, steps away, comes back, and finally opens the gate. Her face fills with unease." + SILENT),
 (18, '10s', [M, S, W], "In the daylit parlour, with Mrs White (the same elderly grey-haired woman with a bun, cream knitted shawl and dark green dress as in the reference) and Mr White, the stranger in the black frock coat stands holding his top hat in both hands, unable to meet their eyes, and says in Uzbek: \"Men Mo va Megginz fabrikasidan keldim.\" Mrs White asks anxiously in Uzbek: \"Gerbertga nima bo'ldi? U yaralandimi?\" The stranger lowers his eyes and says quietly in Uzbek: \"Uni mashina tortib ketdi.\"" + TALK),
 (19, '10s', [S, W, M], "Mr White, seated beside his wife, grips her hand, both pale. The stranger says softly in Uzbek: \"Fabrika sizga tovon puli bermoqchi.\" Mr White whispers in Uzbek: \"Qancha?\" The stranger answers in Uzbek: \"Ikki yuz funt.\" Mrs White's face crumples; Mr White stares into nothing. Slow push-in on Mr White's face." + TALK),
 (20, '8s', [W, M], "A bleak hillside cemetery in grey drizzle. The elderly couple in black mourning clothes stand under one black umbrella before a fresh grave with a simple wooden cross and wet earth. Wide shot, slowly drifting sideways. Sound: rain, distant crows." + SILENT),
 (21, '6s', [ROOM, H], "The silent empty parlour at dusk, no people: Herbert's grey flat cap hangs on a hook by the door, his empty chair stands beside the cold dark fireplace, a clock ticks. Slow push-in on the cap." + SILENT),
 (22, '8s', [M, W], "Night, a dark bedroom lit by pale moonlight. Mrs White, lying in bed weeping softly, suddenly sits bolt upright, eyes wide, and cries in Uzbek: \"Panja! Maymun panjasi!\" Mr White wakes beside her, startled." + TALK),
 (23, '10s', [M, W], "In the moonlit bedroom Mrs White grips her husband's arm feverishly and says in Uzbek: \"Biz faqat bitta tilak tiladik. O'g'limizni tirik qaytarishni tila!\" Mr White, frightened, says in Uzbek: \"Nima deyotganingni o'zing bilmayapsan.\"" + TALK),
 (24, '8s', [W, ROOM], "Mr White in a nightshirt walks down a dark staircase holding a single candle, enters the cold dark parlour and takes the monkey-paw talisman from the mantelpiece. His hand trembles and the candle flame shakes. Sound: creaking stairs." + SILENT),
 (25, '10s', [M, W], "In the candle-lit bedroom Mrs White, standing, cries in Uzbek: \"Tila!\" Mr White, trembling, raises the monkey-paw talisman and says in Uzbek: \"O'g'limning tirilishini tilayman.\" The paw falls from his fingers to the floor and the candle flame gutters out, plunging the room into darkness." + TALK),
 (26, '8s', [W, M], "Near darkness. The old couple lie rigid in bed, listening, their faces barely visible in faint moonlight. A clock ticks; a stair creaks somewhere below." + SILENT),
 (27, '8s', [], "A dark empty hallway at the foot of a staircase in a small Victorian cottage, pale moonlight through the frosted glass panel of the front door. A single loud knock sounds on the door, then silence, then a second knock. The camera slowly creeps toward the door. Horror atmosphere." + SILENT + STYLE.replace(' consistent faces and costumes as in the reference images.', '')),
 (28, '10s', [M, W], "In the dark bedroom Mrs White leaps out of bed and runs to the door, crying in Uzbek: \"Bu Gerbert!\" Mr White grabs her arm and pleads in terror in Uzbek: \"Xudo haqqi, uni ichkariga kiritma!\" She tears free and rushes out toward the stairs." + TALK),
 (29, '8s', [M], "At the front door in the dark hallway, Mrs White in her white nightgown struggles with the heavy iron bolt and chain while loud frantic knocking shakes the door. She cries in Uzbek: \"Kelyapman, Gerbert!\"" + TALK),
 (30, '10s', [W, ROOM], "In the dark parlour Mr White crawls on his hands and knees, searching frantically across the floor in faint moonlight while knocking echoes through the house. He finds the monkey-paw talisman, clutches it to his chest and, eyes shut, silently mouths a desperate wish." + SILENT),
 (31, '10s', [M], "The knocking stops instantly. Mrs White pulls back the bolt and the front door swings open: outside lies the empty moonlit road, quiet and deserted, a light wind stirring the leaves. She stands frozen in the doorway, then her shoulders shake as she sobs." + SILENT),
 (32, '8s', [], "Wide night shot of a lonely country road outside a small brick cottage; a single old gas street lamp opposite flickers over the wet road. The road is completely empty: no people, no figures, no animals, nothing moves except the lamp light and drifting leaves. The camera slowly cranes up into the dark sky. Only the wind." + SILENT + STYLE.replace(' consistent faces and costumes as in the reference images.', '')),
]

if __name__ == '__main__':
    os.makedirs(os.path.join(HERE, 'shots'), exist_ok=True)
    for n, dur, refs, prompt in SHOTS:
        full = prompt if prompt.endswith('no music.') else prompt + STYLE
        with open(os.path.join(HERE, 'shots', f'{n:02d}.json'), 'w', encoding='utf-8') as f:
            json.dump({'refs': refs, 'duration': dur, 'prompt': full}, f, ensure_ascii=False, indent=1)
    print(len(SHOTS), 'shots written')
